#!/usr/bin/env bash
# Scene spec v2, consolidated run (replaces run_v2.sh / run_v2b.sh after the 2026-09-18 18:00 diffusion hang).
#
# Datasets (already generated by run_v2.sh / collect.py):
#   clean  : expert with no disturbance                         (119 eps)
#   mix    : ~15 % of episodes get one kick + expert recovery    (113 eps)  <- the set we expect to be best
#   robust : almost every episode kicked (kept for comparison)   (113 eps)
#   state  : clean, privileged brick poses instead of cameras    (119 eps)
#
# Every policy is evaluated twice on 100 unseen initial states: without a kick, and with one kick at a random
# moment (eval_policy.py --disturb 1.0) which is what the recovery data is supposed to buy.
#
# train() runs lerobot-train under a watchdog: if its log goes quiet for STALL_S the run is killed and resumed
# from its last checkpoint (a 60k-step diffusion run hung at 43k with the GPU idle and one CPU thread spinning).
set -uo pipefail
cd "$(dirname "$0")"
source venv/bin/activate
export MUJOCO_GL=egl
POS=${POS:-0.005}; YAW=${YAW:-10}; EVAL_EPS=${EVAL_EPS:-100}; SEED0=${SEED0:-10000}
STALL_S=${STALL_S:-600}; WORKERS=${WORKERS:-4}
mkdir -p outputs logs
stamp () { date "+%H:%M:%S"; }

train () {  # train <dataset> <policy> <steps> [extra lerobot-train args...]
  local ds=$1 pol=$2 steps=$3; shift 3
  local out="outputs/${pol}_${ds}" log="logs/train_${pol}_${ds}.log"
  if grep -q "End of training" "$log" 2>/dev/null; then echo "[$(stamp)] TRAIN ${pol}_${ds} already done"; return 0; fi
  local attempt
  for attempt in 1 2 3; do
    local -a args
    if [ "$attempt" -gt 1 ] && [ -f "$out/checkpoints/last/pretrained_model/train_config.json" ]; then
      echo "[$(stamp)] TRAIN ${pol}_${ds} resume (attempt $attempt)"
      args=(--config_path="$out/checkpoints/last/pretrained_model/train_config.json" --resume=true)
    else
      echo "[$(stamp)] TRAIN ${pol}_${ds} start (${steps} steps, attempt $attempt)"
      args=(--dataset.repo_id="local/$ds" --dataset.root="data/$ds" --policy.device=cuda --policy.push_to_hub=false
            --steps="$steps" --num_workers="$WORKERS" --save_freq=5000 --log_freq=200
            --output_dir="$out" --job_name="${pol}_${ds}" --wandb.enable=false "$@")
    fi
    lerobot-train "${args[@]}" >> "$log" 2>&1 &
    local pid=$!
    while kill -0 "$pid" 2>/dev/null; do
      sleep 60
      local age=$(( $(date +%s) - $(stat -c %Y "$log" 2>/dev/null || echo 0) ))
      if [ "$age" -gt "$STALL_S" ]; then
        echo "[$(stamp)] TRAIN ${pol}_${ds} STALLED ${age}s -> kill"
        kill -9 "$pid" 2>/dev/null; sleep 5; break
      fi
    done
    wait "$pid" 2>/dev/null
    if grep -q "End of training" "$log" 2>/dev/null; then echo "[$(stamp)] TRAIN ${pol}_${ds} done"; return 0; fi
    sleep 10
  done
  echo "[$(stamp)] TRAIN ${pol}_${ds} FAILED after 3 attempts"
  return 1
}

evaluate () {  # evaluate <run> <mortar> <disturb 0|1.0> [extra eval_policy.py args...]  (background)
  local run=$1 mortar=$2 dist=$3; shift 3
  local tag="$mortar"; [ "$dist" != "0" ] && tag="${mortar}_kick"
  [ -d "outputs/$run/checkpoints/last" ] || { echo "[$(stamp)] EVAL ${run} @ ${tag} skipped (no checkpoint)"; return 0; }
  [ -f "outputs/eval_${run}_${tag}.json" ] && { echo "[$(stamp)] EVAL ${run} @ ${tag} already done"; return 0; }
  echo "[$(stamp)] EVAL ${run} @ ${tag} start (${EVAL_EPS} episodes, background)"
  ( python eval_policy.py --task 2p1 --mortar "$mortar" --ckpt "outputs/$run/checkpoints/last/pretrained_model" \
      --episodes "$EVAL_EPS" --seed0 "$SEED0" --pos-rand "$POS" --yaw-rand "$YAW" --size-rand 0 --disturb "$dist" \
      --out "outputs/eval_${run}_${tag}.json" "$@" > "logs/eval_${run}_${tag}.log" 2>&1 \
    && echo "[$(stamp)] EVAL ${run} @ ${tag} done" || echo "[$(stamp)] EVAL ${run} @ ${tag} FAILED" ) &
}

SMOL_MAP='{"observation.images.front":"observation.images.camera1","observation.images.wrist":"observation.images.camera2"}'
C=v2_2p1_joint_image_clean; R=v2_2p1_joint_image_robust; M=v2_2p1_joint_image_mix; S=v2_2p1_joint_state_clean

# the two policies that already exist only need the kick evaluation
evaluate act_$C mortarB 1.0
evaluate act_$R mortarB 1.0

train $M act 40000 --policy.type=act --batch_size=32
evaluate act_$M mortarB 0
evaluate act_$M mortarB 1.0
evaluate act_$M mortarA 0

train $C diffusion 60000 --policy.type=diffusion --batch_size=32
evaluate diffusion_$C mortarB 0
evaluate diffusion_$C mortarB 1.0

train $M diffusion 60000 --policy.type=diffusion --batch_size=32
evaluate diffusion_$M mortarB 0
evaluate diffusion_$M mortarB 1.0

train $C smolvla 20000 --policy.path=lerobot/smolvla_base --policy.empty_cameras=1 --rename_map="$SMOL_MAP" --batch_size=32
evaluate smolvla_$C mortarB 0 --rename-map "$SMOL_MAP"
evaluate smolvla_$C mortarB 1.0 --rename-map "$SMOL_MAP"

train $M smolvla 20000 --policy.path=lerobot/smolvla_base --policy.empty_cameras=1 --rename_map="$SMOL_MAP" --batch_size=32
evaluate smolvla_$M mortarB 0 --rename-map "$SMOL_MAP"
evaluate smolvla_$M mortarB 1.0 --rename-map "$SMOL_MAP"

train $S act 40000 --policy.type=act --batch_size=32
evaluate act_$S mortarB 0

train $R diffusion 60000 --policy.type=diffusion --batch_size=32
evaluate diffusion_$R mortarB 0
evaluate diffusion_$R mortarB 1.0

wait
echo "[$(stamp)] ALL DONE (v3)"
python summarize.py
